// src/components/Dolar.js
import React, { useEffect, useState } from 'react';
import axios from 'axios';
import { Line } from 'react-chartjs-2';
import Chart from 'chart.js/auto';

const Dolar = () => {
    const [data, setData] = useState([]);
    const [labels, setLabels] = useState([]);
    const API_KEY = '7487e94f8f-82434b0371-skncut';
    const url = 'https://api.fastforex.io/fetch-one?from=USD&to=MXN'; // Asegúrate de usar la URL correcta

    const obtenerPrecioDolar = async () => {
        try {
            const response = await axios.get(url, {
                headers: {
                    'Authorization': `Bearer ${API_KEY}`,
                },
            });
            return response.data.price; // Ajusta según la estructura de la respuesta
        } catch (error) {
            console.error("Error al obtener el precio del dólar:", error);
            return null;
        }
    };

    useEffect(() => {
        const fetchData = async () => {
            const precios = [];
            const fechas = [];
            for (let i = 0; i < 5; i++) {
                const precio = await obtenerPrecioDolar();
                if (precio !== null) {
                    precios.push(precio);
                    fechas.push(new Date().toLocaleTimeString());
                    console.log(`Precio obtenido: ${precio}`); // Agrega esto para ver cada precio
                }
                await new Promise(resolve => setTimeout(resolve, 10000)); // Espera 60 segundos
            }
            console.log("Precios acumulados:", precios); // Agrega esto para ver todos los precios
            setData(precios);
            setLabels(fechas);
        };
    
        fetchData();
    }, []);
    
    const chartData = {
        labels: labels,
        datasets: [
            {
                label: 'Precio del Dólar (MXN)',
                data: data,
                borderColor: 'rgba(75,192,192,1)',
                backgroundColor: 'rgba(75,192,192,0.2)',
                fill: true,
            },
        ],
    };

    return (
        <div>
            <h1>Precio del Dólar en Tiempo Real</h1>
            {data.length > 0 ? (
                <Line data={chartData} />
            ) : (
                <p>Cargando datos...</p>
            )}
        </div>
    );
    
};

export default Dolar;
